interface Vehicle {
    void start();
    void stop();
}

class Car implements Vehicle {
    public void start() { System.out.println("Car started"); }
    public void stop() { System.out.println("Car stopped"); }
}

class Bike implements Vehicle {
    public void start() { System.out.println("Bike pedaling"); }
    public void stop() { System.out.println("Bike brakes"); }
}

solution:
public class Main {
    public static void main(String[] args) {
        Vehicle v1 = new Car();
        Vehicle v2 = new Bike();
        v1.start(); v1.stop();
        v2.start(); v2.stop();
    }
}

